actions.script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.security.MessageDigest

// 1. Map mode string to enumId
Map modeMap = [
    'plan': 'AamPlan', 'build': 'AamBuild', 'orchestrate': 'AamOrchestrate',
    'test': 'AamTest', 'query': 'AamQuery', 'history': 'AamHistory', 'discuss': 'AamDiscuss'
]
String modeEnumId = modeMap.get(mode.toLowerCase()) ?: 'AamPlan'

// 2. Normalize and compute content hash
Map rawPayloadMap = payload ?: [:]
if (userPromptText) rawPayloadMap.userPromptText = userPromptText
String payloadJsonStr = JsonOutput.toJson(rawPayloadMap)

MessageDigest md = MessageDigest.getInstance("SHA-256")
String sha256Hex = md.digest(payloadJsonStr.getBytes("UTF-8")).encodeHex().toString()

// 3. Resolve or create AgiArtifact
String artId = null
if (artifactUri) {
    def artVal = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", artifactUri).one()
    if (!artVal) {
        artVal = ec.entity.makeValue("org.moqui.ai.AgiArtifact")
        artVal.artifactPath = artifactUri
        artVal.artifactStatusEnumId = "AasDraft"
        artVal.setSequencedIdPrimary()
        artVal.create()
    }
    artId = artVal.agiArtifactId
}

// 4. Create or Update AgiPayload entity
def payloadVal = agiPayloadId ? ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one() : null
if (!payloadVal) {
    payloadVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload")
    payloadVal.setSequencedIdPrimary()
    payloadVal.createdDate = ec.user.nowTimestamp
    payloadVal.statusId = "PlsDraft"
} else {
    payloadVal.revisionNumber = (payloadVal.revisionNumber ?: 1) + 1
}

payloadVal.modeEnumId = modeEnumId
payloadVal.targetComponent = targetComponent
payloadVal.artifactUri = artifactUri
payloadVal.targetMariaId = targetMariaId
payloadVal.agiArtifactId = artId
payloadVal.title = title ?: (userPromptText ? (userPromptText.length() > 50 ? userPromptText.substring(0, 47) + "..." : userPromptText) : "Untitled Payload")
payloadVal.userPromptText = userPromptText
payloadVal.payloadJsonData = payloadJsonStr
payloadVal.contentSha256 = sha256Hex
payloadVal.lastUpdatedStamp = ec.user.nowTimestamp

// 5. Contextual Intent Promotion: Map Prompt -> WorkEffort Intent Node
if (["AamBuild", "AamTest", "AamDiscuss"].contains(modeEnumId) && artId) {
    String weType = modeEnumId == "AamDiscuss" ? "WetDiscussion" : "WetIntent"
    String safeMariaId = targetMariaId ?: (artifactUri ? org.moqui.ide.ScreenEditorServices.generateMariaId(artifactUri, "root") : null)

    Map weResult = ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
        workEffortName: payloadVal.title,
        agiArtifactId: artId,
        sourceReferenceId: artifactUri,
        workEffortTypeEnumId: weType,
        targetMariaId: safeMariaId
    ]).call()

    payloadVal.workEffortId = weResult.workEffortId
}

payloadVal.createOrUpdate()
context.agiPayloadId = payloadVal.agiPayloadId
context.workEffortId = payloadVal.workEffortId

// 6. Persist key-value Facets
if (facets instanceof Map) {
    facets.each { k, v ->
        if (k && v != null) {
            def facetVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayloadFacet")
            facetVal.setSequencedIdPrimary()
            facetVal.agiPayloadId = payloadVal.agiPayloadId
            facetVal.facetKey = k.toString()
            facetVal.facetValue = v.toString()
            facetVal.create()
        }
    }
}

// 7. Mode-Specific Pipeline Execution
Map execResult = [:]
if (modeEnumId == "AamBuild") {
    // Execute staged AST mutation if present in payload
    if (rawPayloadMap.stagedAstMutation && artifactUri) {
        payloadVal.statusId = "PlsExecuting"
        payloadVal.update()

        String astJson = JsonOutput.toJson(rawPayloadMap.stagedAstMutation)
        ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer")
            .parameters([artifactUri: artifactUri, metaJsonBuffer: astJson])
            .call()
        ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.save#ScreenXml")
            .parameters([artifactUri: artifactUri, metaJsonBuffer: astJson])
            .call()

        payloadVal.statusId = "PlsCommitted"
        execResult.status = "SUCCESS"
        execResult.message = "Successfully applied AST mutation to ${artifactUri}"
    } else {
        payloadVal.statusId = "PlsStaged"
        execResult.status = "STAGED"
        execResult.message = "Build payload staged for AI assistant code generation."
    }
} else if (modeEnumId == "AamTest") {
    payloadVal.statusId = "PlsStaged"
    execResult.status = "READY"
    execResult.message = "Test payload ready for execution in test harness."
} else {
    payloadVal.statusId = "PlsDraft"
    execResult.status = "RECORDED"
    execResult.message = "Payload context and intent saved."
}

payloadVal.executionResultJson = JsonOutput.toJson(execResult)
payloadVal.update()

context.statusId = payloadVal.statusId
context.executionResult = execResult

import groovy.json.JsonSlurper

def pld = ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one()
if (!pld) {
    ec.message.addError("AgiPayload not found for ID: ${agiPayloadId}")
    return
}

Map outMap = pld.getMap()
if (pld.payloadJsonData) {
    try {
        outMap.payload = new JsonSlurper().parseText(pld.payloadJsonData)
    } catch (Exception ignore) {}
}
if (pld.executionResultJson) {
    try {
        outMap.executionResult = new JsonSlurper().parseText(pld.executionResultJson)
    } catch (Exception ignore) {}
}

def facets = ec.entity.find("org.moqui.ai.payload.AgiPayloadFacet").condition("agiPayloadId", agiPayloadId).list()
outMap.facets = facets.collectEntries { [(it.facetKey): it.facetValue] }

context.payloadDetails = outMap
